// ─── Stage 05 input writer ───────────────────────────────────────────────────
// Writes /tmp/odoo_05_master_data_input.json for 05_master_data_exporter.js
//
// SIZING GUIDE — pass these keys to control extraction throughput and memory:
//
//   page_limit (default 200):
//     Records fetched per search_read call.
//     200  → safe for all model sizes, ~40-90 min runtime for full Stage 05
//     500  → faster on fast/local Odoo; may OOM on stock.move or mail.message
//     50   → use if extraction keeps timing out or n8n container OOMs
//
//   cross_ref_sample_limit (default 50000):
//     Max rows read per Stage 01/02 JSONL file for cross-reference ID harvest.
//     50000 → ensures all referenced partner/product/user IDs are collected
//     5000  → faster cold start, may miss partners/products on larger datasets
//
// n8n instance settings required for Stage 05:
//   Workflow execution timeout: >= 3600 seconds
//   (Workflow Settings → Execution Timeout)
//
// Docker environment recommendation:
//   Add NODE_OPTIONS=--max-old-space-size=1536 to the n8n service in docker-compose.yml
//   for datasets where stock.move > 50,000 rows or mail.message > 100,000 rows.

const fs = require('fs');
const input = { ...$input.first().json };

if (input.odoo_api_key_or_password) {
  input.odoo_api_key_or_password = String(input.odoo_api_key_or_password).trim();
}

// Apply defaults if caller did not specify sizing params
if (!input.page_limit)              input.page_limit = 200;
if (!input.cross_ref_sample_limit)  input.cross_ref_sample_limit = 50000;
if (!input.max_anomaly_evidence_rows) input.max_anomaly_evidence_rows = 500;

const inputPath = '/tmp/odoo_05_master_data_input.json';
fs.writeFileSync(inputPath, JSON.stringify(input), 'utf8');

return [{
  json: {
    ok: true,
    input_path: inputPath,
    snapshot_id: input.snapshot_id,
    page_limit: input.page_limit,
    cross_ref_sample_limit: input.cross_ref_sample_limit,
    message: 'Input JSON written for Stage 05 master data exporter',
  },
}];

const item = $input.first().json;

if (item.exitCode !== undefined && Number(item.exitCode) !== 0) {
  throw new Error(
    `Stage 05 master data exporter failed (exit ${item.exitCode}). stderr: ${item.stderr || ''}`,
  );
}

const stdout = String(item.stdout || '').trim();
if (!stdout) {
  throw new Error(
    `Stage 05 master data exporter returned empty stdout. stderr: ${item.stderr || ''}`,
  );
}

const lastLine = stdout.split(/\r?\n/).filter(Boolean).pop();

try {
  return [{ json: JSON.parse(lastLine) }];
} catch (e) {
  throw new Error(
    `Could not parse Stage 05 exporter stdout as JSON: ${e.message}. stdout starts: ${stdout.slice(0, 500)}`,
  );
}
